const items = $input.all();

return items.map((item) => {
  const raw = (item.json.content?.parts ?? [])
    .filter(part => !part.thought && typeof part.text === 'string')
    .map(part => part.text)
    .join('');

  if (!raw.trim()) {
    throw new Error('Gemini returned an empty response.');
  }

  // Remove optional Markdown code fences.
  const cleaned = raw
    .trim()
    .replace(/^```(?:json)?\s*/i, '')
    .replace(/\s*```$/i, '');

  let result;

  try {
    result = JSON.parse(cleaned);
  } catch (error) {
    throw new Error(
      'Invalid JSON returned by Gemini: ' + error.message
    );
  }

  if (
    typeof result.summary !== 'string' ||
    !Array.isArray(result.key_points) ||
    result.key_points.length !== 5 ||
    !result.key_points.every(p => typeof p === 'string') ||
    !Array.isArray(result.action_items) ||
    !result.action_items.every(a => typeof a === 'string')
  ) {
    throw new Error(
      'Gemini response does not match the expected structure.'
    );
  }

  return {
    json: {
      summary: result.summary,
      key_points: result.key_points,
      action_items: result.action_items
    }
  };
});

